223	    fn should_run(&self, ctx: &ContextHost) -> bool {
224	        // ignore .d.ts and vue/svelte/astro files.
225	        // 1. declarations have side effects (they get merged together)
226	        // 2. vue/svelte/astro scripts declare variables that get used in the template, which
227	        //    we can't detect
228	        !ctx.source_type().is_typescript_definition()
229	            && !ctx
230	                .file_extension()
231	                .is_some_and(|ext| ext == "vue" || ext == "svelte" || ext == "astro")
232	    }
