215	    // Binds the FormalParameters's rest of a function or method.
216	    fn bind(&self, builder: &mut SemanticBuilder<'a>) {
217	        let parent_kind = builder.nodes.parent_kind(builder.current_node_id);
218	        let AstKind::FormalParameters(_) = parent_kind else {
219	            return;
220	        };
221	
222	        let includes = SymbolFlags::FunctionScopedVariable;
223	        let excludes =
224	            SymbolFlags::FunctionScopedVariable | SymbolFlags::FunctionScopedVariableExcludes;
225	        self.bound_names(&mut |ident| {
226	            let symbol_id = builder.declare_symbol(ident.span, ident.name, includes, excludes);
227	            ident.symbol_id.set(Some(symbol_id));
228	        });
229	    }
