2	//! # Semantic Analysis Example
3	//!
4	//! This example demonstrates how to use Oxc's semantic analyzer to perform symbol analysis
5	//! and scope resolution on JavaScript and TypeScript code.
6	//!
7	//! ## Usage
8	//!
9	//! Create a `test.js` file and run:
10	//! ```bash
11	//! cargo run -p oxc_semantic --example semantic [filename] [--symbols] [--symbol-references]
12	//! ```
13	//!
14	//! ## Options
15	//!
16	//! - `--symbols`: Display symbol table and reference information
17	//! - `--symbol-references`: Display detailed reference information for each symbol
18	
19	use std::{env, path::Path, sync::Arc};
20	
21	use itertools::Itertools;
22	
23	use oxc_allocator::Allocator;
24	use oxc_diagnostics::{GraphicalReportHandler, OxcDiagnostic};
25	use oxc_parser::Parser;
26	use oxc_semantic::SemanticBuilder;
27	use oxc_span::{GetSpan, SourceType};
28	
29	// Instruction:
30	// create a `test.js`,
31	// run `cargo run -p oxc_semantic --example semantic`
32	// or `just watch "run -p oxc_semantic --example semantic"`
33	
34	/// Perform semantic analysis on a JavaScript or TypeScript file
35	fn main() -> std::io::Result<()> {
36	    let name = env::args().nth(1).unwrap_or_else(|| "test.js".to_string());
37	    let show_symbols = env::args().skip(1).any(|arg| arg == "--symbols");
38	    let show_symbol_references = env::args().skip(1).any(|arg| arg == "--symbol-references");
39	    let path = Path::new(&name);
40	    let source_text = Arc::new(std::fs::read_to_string(path)?);
41	    let source_type = SourceType::from_path(path).unwrap();
42	    // Memory arena where Semantic and Parser allocate objects
43	    let allocator = Allocator::default();
44	
45	    // Parse the source text into an AST
46	    let parser_ret = Parser::new(&allocator, &source_text, source_type).parse();
47	    if !parser_ret.errors.is_empty() {
48	        let error_message: String = parser_ret
49	            .errors
50	            .into_iter()
51	            .map(|error| format!("{:?}", error.with_source_code(Arc::clone(&source_text))))
52	            .join("\n");
53	        println!("Parsing failed:\n\n{error_message}");
54	        return Ok(());
55	    }
56	
57	    let program = parser_ret.program;
58	
59	    // Build semantic model with syntax error checking
60	    let semantic = SemanticBuilder::new()
61	        // Enable additional syntax checks not performed by the parser
62	        .with_check_syntax_error(true)
63	        .build(&program);
64	
65	    // Report semantic analysis errors
66	    if !semantic.errors.is_empty() {
67	        let error_message: String = semantic
68	            .errors
69	            .into_iter()
70	            .map(|error| format!("{:?}", error.with_source_code(Arc::clone(&source_text))))
71	            .join("\n");
72	        println!("Semantic analysis failed:\n\n{error_message}");
73	    }
74	
75	    // Display symbol information if requested
76	    if show_symbols {
77	        let scoping = semantic.semantic.scoping();
78	        for symbol_id in scoping.symbol_ids() {
79	            let name = scoping.symbol_name(symbol_id);
80	            let flags = scoping.symbol_flags(symbol_id);
81	            println!("Symbol: {name}, ID: {symbol_id:?}, Flags: {flags:?}");
82	            for reference_id in scoping.get_resolved_reference_ids(symbol_id) {
83	                let reference = scoping.get_reference(*reference_id);
84	                println!("  Reference ID: {reference_id:?}, Flags: {:?}", reference.flags());
85	            }
86	        }
87	    }
88	
89	    if show_symbol_references {
90	        let reporter = GraphicalReportHandler::new();
91	
92	        for sym in semantic.semantic.scoping().symbol_ids() {
93	            let symbol_name = semantic.semantic.scoping().symbol_name(sym);
94	            let declaration_span = semantic.semantic.scoping().symbol_span(sym);
95	
96	            let reference_spans = semantic.semantic.symbol_references(sym).map(|reference| {
97	                (
98	                    semantic.semantic.nodes().get_node(reference.node_id()).kind().span(),
99	                    reference.flags(),
100	                )
101	            });
102	
103	            let has_zero_references = semantic.semantic.symbol_references(sym).next().is_none();
104	
105	            let mut info = OxcDiagnostic::warn(format!("References for symbol `{symbol_name}`"))
106	                .with_label(declaration_span.primary_label("declared here"))
107	                .and_labels(
108	                    reference_spans
109	                        .map(|(span, flags)| span.label(format!("referenced here: ({flags:?})"))),
110	                );
111	
112	            if has_zero_references {
113	                info = info.with_note("This symbol has no references.");
114	            }
115	
116	            let info = info.with_source_code(Arc::clone(&source_text));
117	
118	            let mut s = String::new();
119	            reporter.render_report(&mut s, info.as_ref()).unwrap();
120	            println!("{s}");
121	        }
122	    }
123	
124	    Ok(())
